108:/**
109: * What the posting reaches and what the candidate may work under, for the
110: * authorization question that names no country of its own.
111: */
112:export interface JobReach {
113:  /** The posting's location line, as the job row holds it. */
114:  location: string | null | undefined;
115:  /** The posting speaking about its own reach (`worldwide`, `us_only`, …). */
116:  remoteScope?: string | null;
117:  /** Countries the candidate may work in, from `profile.eligibility`. */
118:  workCountries: string[];
119:}
120:
121:/**
122: * May the candidate work where this posting's work happens?
123: *
124: * NOT `reachAllows`, and the difference is the whole point. That function
125: * answers "can this candidate take this job", where a worldwide-remote posting
126: * is a yes whatever its location line says. This one answers "is the candidate
127: * authorized in the country the posting names", and there a location line
128: * reading "San Francisco, California, USA" decides even when the row also says
129: * `worldwide` — the scope is the company describing how it hires, the line is
130: * where the work sits, and answering yes to the US on the strength of the
131: * scope is precisely the fabrication this branch exists to stop. Measured
132: * against 40 real postings on 2026-08-19: using `reachAllows` claimed US
133: * authorization on Atlassian (San Francisco) and Overvak (New York), and
134: * denied it on three Brazilian postings for a Brazilian candidate.
135: *
136: * So: a named country decides; only a posting that names none falls back to
137: * "hires anywhere", which means the candidate works from home and is
138: * authorized there.
139: */
140:function whereTheWorkIs(job: JobReach): "yes" | "no" | "unknown" {
141:  const places = namedPlaces(job.location, job.remoteScope);
142:  if (!job.workCountries.length) return "yes";
143:  if (places.countries.length) {
144:    return places.countries.some((c) => job.workCountries.includes(c))
145:      ? "yes"
146:      : "no";
147:  }
148:  if (places.open) return "yes";
149:  return reachAllows(places, job.workCountries) === "yes" ? "yes" : "unknown";
150:}
151:
152:/**
153: * The conservative truthful answer for a question nothing else can answer, or
154: * null when the question has no safe default and must be written from the
155: * profile.
156: *
157: * `job` is only consulted by the implicit-country authorization branch. Absent
158: * it, that branch still answers — with the negative, because a positive with
159: * nothing behind it is the fabrication this module exists to prevent.
160: */
161:export function conservativeDefaultAnswer(
162:  question: string,
163:  job?: JobReach,
164:): ConservativeDefault | null {
165:  const q = question.trim();
166:  if (!q) return null;
167:
168:  // Order matters: a sponsorship question often names the United States too,
169:  // and its true answer is the opposite polarity of the authorization one.
170:  if (SPONSORSHIP_RE.test(q)) {
171:    return {
172:      answer: "Yes — I would require visa sponsorship to work in the US.",
173:      kind: "boolean",
174:      why:
175:        "No document on file says otherwise, and needing sponsorship is what " +
176:        "the absence of one means. Saying no here would assert a status the " +
177:        "candidate has not evidenced.",
178:    };
179:  }
180:  if (US_WORK_AUTHORIZATION_RE.test(q)) {
181:    return {
182:      answer: "No — I am not authorized to work in the United States.",
183:      kind: "boolean",
184:      why:
185:        "Work authorization is a document, and nothing on file evidences one. " +
186:        "The negative claims nothing; the positive would be a fabrication.",
187:    };
188:  }
189:  // Before the job-country branch: a question about the candidate's own
190:  // country names a country too, and its true answer is the opposite one.
191:  if (AUTHORIZATION_WORDS.test(q) && OWN_COUNTRY_AUTHORIZATION_RE.test(q)) {
192:    return {
193:      answer: "Yes — I am authorized to live and work in my own country.",
194:      kind: "boolean",
195:      why:
196:        "The profile says where the candidate lives, and a person may work " +
197:        "where they live. This asks about their own country, not about the " +
198:        "country this role is based in — those have different true answers.",
199:    };
200:  }
201:  if (
202:    AUTHORIZATION_WORDS.test(q) &&
203:    JOB_COUNTRY_AUTHORIZATION_RE.test(q) &&
204:    !RESIDENCE_RE.test(q)
205:  ) {
206:    const reach = whereTheWorkIs(job ?? { location: null, workCountries: [] });
207:    if (reach === "yes") {
208:      return {
209:        answer: "Yes — I am authorized to work where this role is based.",
210:        kind: "boolean",
211:        why:
212:          "The posting's reach includes a country the candidate may work in, " +
213:          "so the positive is evidenced rather than assumed.",
214:      };
215:    }
216:    return {
217:      answer:
218:        "No — I am not authorized to work in the country where this role is based.",
219:      kind: "boolean",
220:      why:
221:        reach === "no"
222:          ? "The posting is based where the candidate has no right to work."
223:          : "Where the posting is based cannot be read from it, and " +
224:            "authorization is a document. The negative claims nothing; the " +
225:            "positive would be a fabrication.",
226:    };
227:  }
228:  if (DEMOGRAPHIC_RE.test(q) || DEMOGRAPHIC_PT_ES_RE.test(q)) {
229:    return {
230:      answer: "Prefer not to say.",
231:      kind: "text",
232:      why:
233:        "Voluntary self-identification. Declining is an answer the form offers " +
234:        "and no employer may hold against it — pick the decline option as the " +
235:        "page words it.",
236:    };
237:  }
238:  return null;
239:}
